import"./hoisted.MHA2R7Ky.js";document.getElementById("contact-form")?.addEventListener("submit",async n=>{n.preventDefault();const a=n.target,s=a.querySelector('button[type="submit"]'),e=document.getElementById("form-toast"),r=new FormData(a);s.disabled=!0,s.innerHTML='<span class="material-symbols-outlined animate-spin">refresh</span> Enviando...';try{const t=await fetch("/api/contact",{method:"POST",body:r}),o=await t.json();if(t.ok&&o.success)e.className="fixed bottom-6 right-6 z-50 px-6 py-4 rounded-lg shadow-lg max-w-sm bg-success text-white",e.innerHTML='<div class="flex items-center gap-3"><span class="material-symbols-outlined">check_circle</span><div><strong>¡Enviado!</strong><br>Te contactaremos en menos de 24hs.</div></div>',a.reset();else throw new Error(o.message||"Error al enviar")}catch(t){e.className="fixed bottom-6 right-6 z-50 px-6 py-4 rounded-lg shadow-lg max-w-sm bg-error text-white",e.innerHTML=`<div class="flex items-center gap-3"><span class="material-symbols-outlined">error</span><div><strong>Error</strong><br>${t.message||"No se pudo enviar. Intentá por WhatsApp o email."}</div></div>`}e.classList.remove("hidden"),s.disabled=!1,s.innerHTML='<span class="material-symbols-outlined">send</span> Enviar solicitud',setTimeout(()=>e.classList.add("hidden"),6e3)});
